doc.codeblock:
/* src/style.css:54-55 */
body {
  user-select: none;
  -webkit-user-select: none;
}

/* .field（src/style.css:290 附近）只设了 outline / border，没有覆盖 user-select */

function render() {
  renderRail();
  renderBoard();
  const key = `${sel}|${selKey}|${draft.kind}`;
  if (key !== inspKey) {
    inspKey = key;
    renderInsp();          // textarea 只在这里创建
  }
}

// 打字只改数据，不碰 DOM
tv.addEventListener("input", () => {
  draft.value = tv.value;
  scheduleWrite(draft.kind === "note" ? "note" : "block", tv.value);
});

// 写盘完成后只更新别处
await refreshChrome();     // rail + board + 删除按钮
paintEffect();             // 绑定摘要 + 已保存徽标
